156	/// The OpenAPI document for `/v1/*`. Built without the dataset summary: it
157	/// is served without auth, so it must not describe the data.
158	pub fn openapi(server: &ServerOptions, base_url: &str) -> Value {
159	    let data = Session::new(server.clone()).data_enabled();
160	    let memory = server.memory.as_ref().map(|m| (m.tools, m.settings.namespace.as_str()));
161	    let tools = mcp::tool_definitions(None, memory, data);
162	    let mut paths = serde_json::Map::new();
163	    for tool in tools.as_array().into_iter().flatten() {
164	        let name = tool["name"].as_str().unwrap_or_default();
165	        // GPT Actions caps descriptions at 300 characters.
166	        let description: String =
167	            tool["description"].as_str().unwrap_or_default().chars().take(300).collect();
168	        let summary = description.split(". ").next().unwrap_or(name).chars().take(120).collect::<String>();
169	        paths.insert(
170	            format!("/v1/{name}"),
171	            json!({"post": {
172	                "operationId": name,
173	                "summary": summary,
174	                "description": description,
175	                "requestBody": {"required": true, "content": {"application/json": {"schema": tool["inputSchema"]}}},
176	                "responses": {
177	                    "200": {"description": "The tool result as JSON", "content": {"application/json": {"schema": {"type": "object"}}}},
178	                    "400": {"description": "Bad arguments or a refused write",
179	                            "content": {"application/json": {"schema": {"$ref": "#/components/schemas/Error"}}}},
180	                    "401": {"description": "Missing or wrong bearer token"}
181	                }
182	            }}),
183	        );
184	    }
185	    json!({
186	        "openapi": "3.1.0",
187	        "info": {"title": "Leviathan", "version": env!("CARGO_PKG_VERSION"),
188	                 "description": "Search an index of records and read and write agent memory."},
189	        "servers": [{"url": base_url}],
190	        "paths": paths,
191	        "components": {
192	            "securitySchemes": {"bearer": {"type": "http", "scheme": "bearer"}},
193	            "schemas": {"Error": {"type": "object", "properties": {"error": {"type": "string"}}, "required": ["error"]}}
194	        },
195	        "security": [{"bearer": []}]
196	    })
197	}
